#include <iostream>
#include <utility>
#include <queue>
using namespace std;
typedef long long ll;
typedef pair<int, int> P;
const ll inf = 1e18;

int n, m;
vector<int> G[200005];
bool visited[200005];
vector<P> T1, T2;

void dfs(int v)
{
  visited[v] = true;
  for(auto u : G[v]){
    if(!visited[u]){
      T1.push_back(P(v, u));
      dfs(u);
    }
  }
}
void bfs()
{
  for(int i = 1; i <= n; i++) visited[i] = false;
  queue<int> Q;
  Q.push(1), visited[1] = true;

  int v;
  while(Q.size()){
    v = Q.front(), Q.pop();
    for(auto u : G[v]){
      if(!visited[u]){
        T2.push_back(P(v, u));
        visited[u] = true;
        Q.push(u);
      }
    }
  }
}

int main(void)
{
  cin >> n >> m;
  int u, v;
  for(int i = 1; i <= m; i++){
    cin >> u >> v;
    G[u].push_back(v);
    G[v].push_back(u);
  }

  dfs(1);
  bfs();

  for(auto p : T1) cout << p.first << " " << p.second << "\n";
  for(auto p : T2) cout << p.first << " " << p.second << "\n";

  return 0;
}
